#include <cstdint>

// Returns the minimum number of operations to transform a into b,
// where allowed operations are: replace x by floor(x/2) or by 2*x.
// Precondition: the transformation is possible.
int minTransformations(std::int64_t a, std::int64_t b) {
    int operations = 0;
    while (a != b) {
        if (a > b) {
            a /= 2;         // equivalent to floor(a/2)
        } else {
            b /= 2;         // simulate moving b upward; will be compensated by doubling later
        }
        ++operations;
    }
    return operations;
}

#include <cassert>
#include <cstdint>

int main() {
    // Equal values require no operations.
    assert(minTransformations(5, 5) == 0);
    // Direct halving.
    assert(minTransformations(8, 4) == 1);
    assert(minTransformations(10, 5) == 1);
    // Direct doubling.
    assert(minTransformations(3, 6) == 1);
    assert(minTransformations(7, 14) == 1);
    // Multiple halvings.
    assert(minTransformations(12, 3) == 2);
    // Multiple doublings.
    assert(minTransformations(3, 12) == 2);
    // Mixed path: 5 -> 4 -> 8? Actually 5->2 (halve), 2->8 (double twice) = 3.
    // 5/2=2, then 2*2=4, 4*2=8? That's 3 operations. Our algorithm: a=5,b=8: a<b -> b=4, count1; a=5>4 -> a=2, count2; b=4>2? actually b=4>2 -> b=2, count3; a==b. Works.
    assert(minTransformations(5, 8) == 3);
    // Larger example: 6 and 6? already tested. 6 to 3: 6/2=3, 1 op.
    assert(minTransformations(6, 3) == 1);
    return 0;
}
